<section class="admin-content">
  <div class="admin-section-intro"><div><span class="eyebrow">Customer conversations</span><h2>Service inquiries</h2><p>Review incoming requests and keep the follow-up status current.</p></div></div>
  <section class="admin-panel admin-record-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Inbox</span><h2>All inquiries <span class="admin-count"><?= count($sectionData['records']) ?></span></h2></div></div>
    <?php if (!$sectionData['records']): ?><p class="admin-empty">No inquiries have been received.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Contact</th><th>Service</th><th>Message</th><th>Received</th><th>Follow-up</th></tr></thead><tbody><?php foreach ($sectionData['records'] as $record): ?><tr><td><strong><?= $this->escape($record['name']) ?></strong><small class="table-subtext"><a href="mailto:<?= $this->escape($record['email']) ?>"><?= $this->escape($record['email']) ?></a><?= $record['phone'] ? '<br>' . $this->escape($record['phone']) : '' ?></small></td><td><?= $this->escape($record['service_name'] ?: 'General') ?></td><td class="admin-message-cell"><?= $this->escape(substr($record['message'], 0, 180)) ?><?= strlen($record['message']) > 180 ? '…' : '' ?></td><td><?= $this->escape(date('M j, Y', strtotime($record['created_at']))) ?></td><td><form class="admin-status-form" method="post" action="<?= $this->escape(appUrl('/admin/inquiries/status')) ?>"><input type="hidden" name="csrf" value="<?= $this->escape($_SESSION['csrf'] ?? '') ?>"><input type="hidden" name="id" value="<?= (int) $record['id'] ?>"><label class="sr-only" for="inquiry-status-<?= (int) $record['id'] ?>">Status for inquiry from <?= $this->escape($record['name']) ?></label><select id="inquiry-status-<?= (int) $record['id'] ?>" name="status"><?php foreach (['new'=>'New','in_progress'=>'In progress','responded'=>'Responded','closed'=>'Closed'] as $value=>$label): ?><option value="<?= $this->escape($value) ?>" <?= $record['status'] === $value ? 'selected' : '' ?>><?= $this->escape($label) ?></option><?php endforeach ?></select><button class="button button-small" type="submit">Update</button></form></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
  </section>
</section>
